<!doctype html><html lang="id"><head><meta charset="utf-8"><style>*{box-sizing:border-box}body{font-family:DejaVu Sans,Arial,sans-serif;color:#102235;margin:0}.sheet{border:1px solid #d9e4ed;border-radius:18px;padding:34px}.accent{height:7px;background:linear-gradient(90deg,#0f766e,#06b6d4,#2563eb);border-radius:8px;margin-bottom:28px}.brand{font-size:11px;letter-spacing:2px;color:#0f766e;font-weight:bold;text-transform:uppercase}.title{font-size:27px;margin:9px 0 4px}.muted{color:#64748b;font-size:11px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:28px}.item{border:1px solid #e2e8f0;border-radius:12px;padding:13px}.item small{display:block;color:#64748b;font-size:9px;text-transform:uppercase;letter-spacing:1px}.item strong{display:block;margin-top:7px;font-size:13px}.exam{margin-top:24px;border-radius:14px;background:#effaf8;padding:18px}.exam h2{margin:0 0 5px;font-size:19px}.exam p{font-size:12px;color:#475569;line-height:1.7}.verify{display:flex;align-items:center;gap:18px;border-top:1px solid #e2e8f0;margin-top:34px;padding-top:22px}.qr{width:108px;height:108px}.verify p{font-size:10px;color:#64748b;line-height:1.6}.footer{margin-top:28px;color:#94a3b8;font-size:9px;text-align:center}</style></head><body><main class="sheet"><div class="accent"></div><div class="brand">{{ config('siakad.institution') }} · Kartu Peserta</div><h1 class="title">Kartu Peserta Ujian</h1><div class="muted">{{ strtoupper($exam->exam_type) }} · {{ $exam->academicTerm->name }}</div><div class="grid"><div class="item"><small>Nama mahasiswa</small><strong>{{ $student->user?->name }}</strong></div><div class="item"><small>NIM</small><strong>{{ $student->nim }}</strong></div><div class="item"><small>Program studi</small><strong>{{ $student->program?->name ?? '-' }}</strong></div><div class="item"><small>Kode verifikasi</small><strong>{{ $exam->verification_code }}</strong></div></div><section class="exam"><h2>{{ $exam->classGroup->course->code }} · {{ $exam->classGroup->course->name }}</h2><p>Kelas {{ $exam->classGroup->name }}<br>{{ $exam->exam_date->locale('id')->translatedFormat('l, d F Y') }} · {{ substr($exam->starts_at, 0, 5) }}–{{ substr($exam->ends_at, 0, 5) }}<br>{{ $exam->delivery_mode === 'online' ? 'Daring' : ($exam->room ? $exam->room->building->name.' · '.$exam->room->code.' · '.$exam->room->name : 'Hybrid') }}</p></section><section class="verify"><img class="qr" src="{{ $qrCode }}" alt="QR verifikasi"><div><strong>Verifikasi kartu</strong><p>Pindai QR untuk memeriksa keaslian jadwal ujian pada registri SIAKAD.</p><p>{{ $verificationUrl }}</p></div></section><div class="footer">Kartu diterbitkan oleh sistem secara elektronik. Bawa kartu ini dan identitas mahasiswa saat ujian.</div></main></body></html>
